from lexer import tokenize

def test_empty():
    # Passes before fix
    assert tokenize("") == []

def test_plain_words():
    # Passes before fix
    assert tokenize("hello world foo") == ["hello", "world", "foo"]

def test_simple_quoted():
    # Passes before fix
    assert tokenize('name "hello world" age') == ["name", "hello world", "age"]

def test_escaped_quote():
    # Escaped quote inside string should be preserved as quote
    assert tokenize('msg "he said \\"hi\\"" now') == ["msg", 'he said "hi"', "now"]

