def tokenize(text: str) -> list[str]:
    """Tokenizes string by space, preserving quoted substrings and handles escaped quotes."""
    tokens = []
    current = []
    in_quotes = False
    escaped = False
    for char in text:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '"':
            in_quotes = not in_quotes
        elif char == ' ' and not in_quotes:
            if current:
                tokens.append(''.join(current))
                current = []
        else:
            current.append(char)
    if current:
        tokens.append(''.join(current))
    return tokens
